graphql.query:
query Ranking($city: String!, $countryCode: String) {
  activityRanking(city: $city, countryCode: $countryCode) {
    location { name country countryCode region timezone }
    meta { source fetchedAt nextRefreshAt outdated }
    byActivity { activity score rating bestDay available unavailableReason }
    byDay {
      date
      bestActivity
      weather { condition tempMaxC precipitationMm snowDepthCm waveHeightMaxM }
      activities { activity score rating summary reasons }
    }
  }
}

